parameters = {
    'attributeType': 'Line',
    'attributes': [{'attributeId': toDelete['attributeId'], 'replacementAttributeId': replacement['attributeId']}]
}
aclib.PrintJson (aclib.RunTapirCommand ('DeleteAndReplaceAttributes', dict (parameters, dryRun = True)))
